YR(a){return a+" (+1)"},
b42(a,b){return"\u041e\u0442\u0433\u043e\u0432\u043e\u0440\u0435\u0442\u0435 \u0434\u043e "+a+" (\u043e\u0441\u0442\u0430\u0432\u0430\u0442 "+b+"). \u041d\u0438\u0449\u043e \u043d\u0435 \u0441\u0435 \u0442\u0430\u043a\u0441\u0443\u0432\u0430, \u0434\u043e\u043a\u0430\u0442\u043e \u043d\u0435 \u043f\u043e\u0442\u0432\u044a\u0440\u0434\u0438\u0442\u0435; \u0442\u043e\u0433\u0430\u0432\u0430 \u043a\u0430\u0440\u0442\u0430\u0442\u0430 \u043d\u0430 \u0432\u043e\u0434\u0430\u0447\u0430 \u0441\u0435 \u0442\u0430\u043a\u0441\u0443\u0432\u0430 (\u0442\u0435\u0441\u0442\u043e\u0432\u043e \u043f\u043b\u0430\u0449\u0430\u043d\u0435). \u0411\u0435\u0437 \u043e\u0442\u0433\u043e\u0432\u043e\u0440 \u0437\u0430\u044f\u0432\u043a\u0430\u0442\u0430 \u043e\u0442\u043f\u0430\u0434\u0430 \u0438 \u043d\u0430 \u0432\u043e\u0434\u0430\u0447\u0430 \u0441\u0435 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0442 \u0434\u0440\u0443\u0433\u0438 \u043c\u0435\u0441\u0442\u0430."},
