gbnw(){return"Stavia \u0435 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430: \u043f\u043e\u043a\u0430\u0437\u0432\u0430 \u0442\u0438 \u043c\u0435\u0441\u0442\u0430, \u043a\u043e\u0438\u0442\u043e \u043e\u0431\u0435\u043a\u0442\u0438\u0442\u0435 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0442, \u0438 \u043f\u0440\u0438\u0435\u043c\u0430 \u043f\u043b\u0430\u0449\u0430\u043d\u0435\u0442\u043e \u0437\u0430 \u0442\u044f\u0445. \u0421\u0430\u043c\u043e\u0442\u043e \u043f\u0430\u0440\u043a\u0438\u0440\u0430\u043d\u0435 \u0435 \u0443\u0441\u043b\u0443\u0433\u0430 \u043d\u0430 \u043e\u0431\u0435\u043a\u0442\u0430, \u043f\u043e \u043d\u0435\u0433\u043e\u0432\u0438\u0442\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u0438 \u043f\u0440\u0435\u0434\u0438 \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0446\u0438\u044f\u0442\u0430; \u0442\u0430\u043a\u0441\u0430\u0442\u0430 \u043d\u0430 Stavia \u0435 \u0437\u0430 \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0446\u0438\u044f\u0442\u0430."},
