gb9W(){return"\u0422\u043e\u0437\u0438 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0435 \u043f\u0430\u043a \u0432 \u0434\u0435\u043c\u043e\u0442\u043e. \u041a\u0430\u043a\u0432\u043e\u0442\u043e \u0437\u0430\u043a\u043e\u043d\u044a\u0442 \u0438\u0441\u043a\u0430 \u0434\u0430 \u043f\u0430\u0437\u0438\u043c, \u043e\u0441\u0442\u0430\u0432\u0430, \u043a\u0430\u043a\u0442\u043e \u043f\u0438\u0448\u0435\u0448\u0435; \u043d\u0438\u0449\u043e \u0434\u0440\u0443\u0433\u043e \u0442\u0432\u043e\u0435 \u043d\u0435 \u043e\u0441\u0442\u0430\u0432\u0430."},
gb9X(){return"\u0414\u043e\u0431\u0440\u0435"},
gba8(){return"\u0412\u0441\u044f\u043a\u043e \u0438\u0437\u0442\u0435\u0433\u043b\u044f\u043d\u0435, \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u0438 \u0438\u0437\u0442\u0440\u0438\u0432\u0430\u043d\u0435 \u0441\u0435 \u0437\u0430\u043f\u0438\u0441\u0432\u0430 \u043a\u0430\u0442\u043e \u0438\u0441\u043a\u0430\u043d\u0435 \u0437\u0430 \u0434\u0430\u043d\u043d\u0438\u0442\u0435 \u0442\u0438. \u041f\u043e\u0432\u0435\u0447\u0435 \u0432 \u201e\u041f\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u043d\u043e\u0441\u0442\u201c."},
gQo(){return"\u0414\u0430\u043d\u043d\u0438\u0442\u0435 \u043c\u0438 \u0432 Stavia"},
gajN(){return"\u0412\u0441\u0438\u0447\u043a\u043e, \u043a\u043e\u0435\u0442\u043e Stavia \u043f\u0430\u0437\u0438 \u0437\u0430 \u0442\u0435\u0431, \u043a\u044a\u043c \u0434\u0435\u043d\u044f \u043d\u0430 \u0438\u0437\u0442\u0435\u0433\u043b\u044f\u043d\u0435\u0442\u043e. \u0424\u0430\u0439\u043b\u044a\u0442 \u0441 \u0434\u0430\u043d\u043d\u0438 \u0434\u043e \u0442\u0430\u0437\u0438 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 \u0441\u044a\u0434\u044a\u0440\u0436\u0430 \u0441\u044a\u0449\u043e\u0442\u043e, \u0437\u0430 \u0434\u0440\u0443\u0433\u0438 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u0438."},
gajO(){return"\u041a\u043e\u043b\u043a\u043e \u0434\u044a\u043b\u0433\u043e \u0441\u0435 \u043f\u0430\u0437\u0438 \u0432\u0441\u0435\u043a\u0438 \u0432\u0438\u0434 \u0434\u0430\u043d\u043d\u0438, \u043f\u0438\u0448\u0435 \u0432 \u201e\u041f\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u043d\u043e\u0441\u0442\u201c \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e; \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0442\u0435 \u0437\u0430 \u043f\u043b\u0430\u0449\u0430\u043d\u0438\u044f \u0441\u0435 \u043f\u0430\u0437\u044f\u0442 \u0434\u043e 31 \u0434\u0435\u043a\u0435\u043c\u0432\u0440\u0438 \u043d\u0430 11-\u0430\u0442\u0430 \u0433\u043e\u0434\u0438\u043d\u0430, \u043a\u0430\u043a\u0442\u043e \u0438\u0441\u043a\u0430 \u0437\u0430\u043a\u043e\u043d\u044a\u0442."},
