gba7(){return"\u0421\u044a\u043e\u0431\u0449\u0435\u043d\u0438\u044f"},
gba3(){return"\u0418\u0441\u043a\u0430\u043d\u0438\u044f \u0437\u0430 \u043f\u043e\u043c\u043e\u0449"},
gbag(){return"\u0412\u0430\u0443\u0447\u0435\u0440\u0438"},
gba9(){return"\u041f\u043b\u0430\u0449\u0430\u043d\u0438\u044f"},
gb9Z(){return"\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438"},
gba6(){return"\u041c\u0435\u0441\u0442\u0430 \u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0430"},
