gbab(){return"\u0421\u0438\u0433\u043d\u0430\u043b\u0438"},
gb9M(){return"\u0421\u044a\u0433\u043b\u0430\u0441\u0438\u044f"},
gbc_(){return"\u0418\u0441\u043a\u0430\u043c \u043f\u0430\u0440\u043a\u0438\u0440\u0430\u043d\u0435\u0442\u043e \u0434\u0430 \u0437\u0430\u043f\u043e\u0447\u043d\u0435 \u0432 \u0438\u0437\u0431\u0440\u0430\u043d\u0438\u044f \u0447\u0430\u0441, \u0432 14-\u0434\u043d\u0435\u0432\u043d\u0438\u044f \u0441\u0440\u043e\u043a \u0437\u0430 \u043e\u0442\u043a\u0430\u0437. \u0417\u043d\u0430\u043c, \u0447\u0435 \u0433\u0443\u0431\u044f \u043f\u0440\u0430\u0432\u043e\u0442\u043e \u043d\u0430 \u043e\u0442\u043a\u0430\u0437, \u0449\u043e\u043c \u043f\u0430\u0440\u043a\u0438\u0440\u0430\u043d\u0435\u0442\u043e \u0431\u044a\u0434\u0435 \u0438\u0437\u0446\u044f\u043b\u043e \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0435\u043d\u043e, \u0430 \u0430\u043a\u043e \u0441\u0435 \u043e\u0442\u043a\u0430\u0436\u0430 \u043f\u043e-\u0440\u0430\u043d\u043e, \u043f\u043b\u0430\u0449\u0430\u043c \u0437\u0430 \u0438\u0437\u043f\u043e\u043b\u0437\u0432\u0430\u043d\u043e\u0442\u043e \u0432\u0440\u0435\u043c\u0435."},
gaex(){return"\u0416\u0430\u043b\u0431\u0438 \u0438 \u0441\u043f\u043e\u0440\u043e\u0432\u0435"},
gaS3(){return"\u0427\u0415\u0420\u041d\u041e\u0412\u0410 \u0437\u0430 \u0430\u0434\u0432\u043e\u043a\u0430\u0442\u0430: \u043d\u0435 \u0435 \u0432 \u0441\u0438\u043b\u0430. \u0412 \u0442\u0435\u0441\u0442\u043e\u0432\u0438\u0442\u0435 \u0441\u0440\u0435\u0434\u0438 \u043d\u0435 \u0441\u0435 \u0442\u0435\u0433\u043b\u044f\u0442 \u0440\u0435\u0430\u043b\u043d\u0438 \u043f\u0430\u0440\u0438."},
