gaS4(){return"\u0417\u0430 \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0446\u0438\u044f: \u043e\u0442\u0432\u043e\u0440\u0438 \u044f \u0438 \u0438\u0437\u0431\u0435\u0440\u0438 \u201e\u041f\u043e\u043c\u043e\u0449\u201c, \u0442\u0430\u043a\u0430 \u0432\u0438\u0436\u0434\u0430\u043c\u0435 \u0432\u0441\u0438\u0447\u043a\u043e, \u043a\u043e\u0435\u0442\u043e \u0435 \u0441\u0442\u0430\u043d\u0430\u043b\u043e. \u0417\u0430 \u0432\u0441\u0438\u0447\u043a\u043e \u0434\u0440\u0443\u0433\u043e: \u201e\u041e\u0431\u0440\u0430\u0442\u043d\u0430 \u0432\u0440\u044a\u0437\u043a\u0430\u201c \u0433\u043e\u0440\u0435 \u043d\u0430 \u0435\u043a\u0440\u0430\u043d\u0430. \u041c\u043e\u0436\u0435\u0448 \u0434\u0430 \u0441\u0435 \u043e\u043f\u043b\u0430\u0447\u0435\u0448 \u043e\u0442 \u043c\u044f\u0441\u0442\u043e\u0442\u043e \u0438\u043b\u0438 \u043e\u0442 Stavia."},
gaSf(){return"\u041a\u0430\u043a\u0432\u043e \u0441\u0442\u0430\u0432\u0430"},
gaSe(){return"\u0412\u0441\u044f\u043a\u0430 \u0436\u0430\u043b\u0431\u0430 \u0441\u0435 \u0432\u043f\u0438\u0441\u0432\u0430 \u0432 \u043d\u0430\u0448\u0438\u044f \u0440\u0435\u0433\u0438\u0441\u0442\u044a\u0440 \u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0432\u0430\u0448 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0441 \u043d\u043e\u043c\u0435\u0440\u0430 \u0438 \u0434\u0430\u0442\u0430\u0442\u0430 \u045d \u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0442\u0435 \u043d\u0430 \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0446\u0438\u044f\u0442\u0430 (\u0417\u0417\u041f \u0447\u043b. 127). \u041f\u043e\u0434\u0434\u0440\u044a\u0436\u043a\u0430\u0442\u0430 \u044f \u043f\u0440\u0435\u0433\u043b\u0435\u0436\u0434\u0430, \u043f\u0438\u0442\u0430 \u043c\u044f\u0441\u0442\u043e\u0442\u043e, \u0430\u043a\u043e \u0442\u0440\u044f\u0431\u0432\u0430, \u0438 \u0442\u0438 \u043e\u0442\u0433\u043e\u0432\u0430\u0440\u044f \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e."},
